%[text] # Performance Testing
%[text:tableOfContents]{"heading":"**Table of Contents**"}
%[text] ## copying table with 1 column and 100,000 rows
import matlab.perftest.TimeExperiment
suiteSingleCol = testsuite("TcopytablePerformance/testSingleColumn");
maxNumberOfSamples = 200;
experimentSingleCol = TimeExperiment.limitingSamplingError(...
    "NumWarmups",5,...
    "RelativeMarginOfError",0.05,...
    "ConfidenceLevel",0.97,...
    "MaxSamples",maxNumberOfSamples);
resultsSingleCol = run(experimentSingleCol, suiteSingleCol); %[output:8df304c2]
histogram(resultsSingleCol.TestActivity.MeasuredTime,'NumBins',20,'Normalization','percentage') %[output:9195b5f1]
title('Timing for copytable on single row') %[output:9195b5f1]
ylabel('Percentage') %[output:9195b5f1]
xlabel('Runtime (sec)') %[output:9195b5f1]
%%
%[text] ## copying table with 316 column and 316 rows
suiteMultiCol = testsuite("TcopytablePerformance/testMultipleColumns");
maxNumberOfSamples = 200;
experimentMultiCol = TimeExperiment.limitingSamplingError(...
    "NumWarmups",5,...
    "RelativeMarginOfError",0.05,...
    "ConfidenceLevel",0.97,...
    "MaxSamples",maxNumberOfSamples);
resultsMultiCol = run(experimentMultiCol, suiteMultiCol); %[output:00139300]
histogram(resultsMultiCol.TestActivity.MeasuredTime,'NumBins',20,'Normalization','percentage') %[output:965abd73]
title('Timing for copytable on multiple columns') %[output:965abd73]
ylabel('Percentage') %[output:965abd73]
xlabel('Runtime (sec)') %[output:965abd73]
%%
%[text] ## Comparison
histogram(resultsMultiCol.TestActivity.MeasuredTime,'NumBins',20,'Normalization','percentage','DisplayName','Multiple Column') %[output:3f5f8ff6]
hold on %[output:3f5f8ff6]
histogram(resultsSingleCol.TestActivity.MeasuredTime,'NumBins',20,'Normalization','percentage','DisplayName','Single Column') %[output:3f5f8ff6]
hold off %[output:3f5f8ff6]
xlabel('Runtime (sec)') %[output:3f5f8ff6]
ylabel('Percentage') %[output:3f5f8ff6]
legend('show') %[output:3f5f8ff6]

